sysauto_script.script:
(function executeSlaMonitor() {

var now = new GlideDateTime();

var gr = new GlideRecord('x_78515_intellig_0_major_incident');
gr.query();

var responseCount = 0;
var resolutionCount = 0;
var escalationCount = 0;

while (gr.next()) {

var updated = false;

var responseBreached =
gr.getValue('response_breached') == 'true' ||
gr.getValue('response_breached') == '1';

var resolutionBreached =
gr.getValue('resolution_breached') == 'true' ||
gr.getValue('resolution_breached') == '1';

var acknowledged =
gr.getValue('response_acknowledged') == 'true' ||
gr.getValue('response_acknowledged') == '1';

// 1. Check response SLA
if (gr.getValue('response_due') &&
!acknowledged &&
!responseBreached) {

var responseDue = new GlideDateTime(
gr.getValue('response_due')
);

if (responseDue.getNumericValue() <
now.getNumericValue()) {

responseBreached = true;
gr.setValue('response_breached', true);

responseCount++;
updated = true;
}
}

// 2. Check resolution SLA
var state = gr.getDisplayValue('state');

if (gr.getValue('resolution_due') &&
state != 'Resolved' &&
state != 'Closed' &&
state != 'Rejected' &&
!resolutionBreached) {

var resolutionDue = new GlideDateTime(
gr.getValue('resolution_due')
);

if (resolutionDue.getNumericValue() <
now.getNumericValue()) {

resolutionBreached = true;
gr.setValue('resolution_breached', true);

resolutionCount++;
updated = true;
}
}

// 3. Determine current escalation
var currentLevel =
parseInt(gr.getValue('escalation_level'), 10) || 0;

var newLevel = currentLevel;

// Level 1: Response breach
if (responseBreached && newLevel < 1) {
newLevel = 1;
}

// Level 2: 15 minutes after Level 1,
// if still unresolved and response not acknowledged
if (currentLevel == 1 &&
responseBreached &&
!acknowledged &&
!resolutionBreached &&
gr.getValue('escalated_at')) {

var escalatedAt = new GlideDateTime(
gr.getValue('escalated_at')
);

var elapsedMinutes =
(now.getNumericValue() -
escalatedAt.getNumericValue()) / 60000;

if (elapsedMinutes >= 15) {
newLevel = 2;
}
}

// Level 3: Resolution breach
if (resolutionBreached && newLevel < 3) {
newLevel = 3;
}

// 4. Apply escalation only when level increases
if (newLevel > currentLevel) {

gr.setValue('escalation_level', String(newLevel));
gr.setValue('escalated_at', now.getValue());

escalationCount++;
updated = true;

if (resolutionBreached) {
gr.setValue('sla_status', 'resolution breached');
} else if (responseBreached) {
gr.setValue('sla_status', 'response breached');
}

// Queue notification event
gs.eventQueue(
'x_78515_intellig_0.mim.escalation',
gr,
String(newLevel),
gr.getValue('short_description')
);

gs.info(
'MIM ESCALATION: Level ' +
newLevel +
' queued for ' +
gr.getUniqueValue()
);
}

// 5. Save record without triggering SLA recalculation
if (updated) {
gr.setWorkflow(false);
gr.update();
}
}

gs.info(
'MIM SLA Monitor: Response breaches=' +
responseCount +
', Resolution breaches=' +
resolutionCount +
', Escalations=' +
escalationCount
);

})();
